 "<b style=\"font-size:25px;color:#e0612b\">Resto</b><br><span style=\"font-size:20px;color:#16202e\">Dentro de márgenes razonables.</span>": "<b style=\"font-size:25px;color:#e0612b\">Gainerakoa</b><br><span style=\"font-size:20px;color:#16202e\">Marjina zentzuzkoen barruan.</span>",
